files.tests/behavior.test.cjs:
const test=require('node:test');
const assert=require('node:assert/strict');
const {checksum}=require('../checksum.cjs');
test('only visible bytes',()=>{
  const storage=Uint8Array.from([99,250,20,77]);
  assert.equal(checksum(storage.subarray(1,3)),14);
  assert.equal(checksum(storage.subarray(2,2)),0);
  assert.deepEqual([...storage],[99,250,20,77]);
  assert.equal(checksum(Buffer.from([1,2,3])),6);
  assert.equal(checksum(new Uint8Array()),0);
  assert.equal(checksum(Uint8Array.from([255,255,255])),253);
});

